-- المحطة المتكررة + الصيانة متعددة الأيام + ثلاثة إسنادات شفت + غرفة العمليات.
do $$
declare g uuid:='83000000-0000-0000-0000-000000000001';m uuid:='83000000-0000-0000-0000-000000000002';st uuid:='83000000-0000-0000-0000-000000000003';mt uuid:='83000000-0000-0000-0000-000000000004';op uuid:='83000000-0000-0000-0000-000000000005';v public.garage_vehicles;d public.garage_departures;l public.vehicle_trip_legs;c public.vehicle_maintenance_cases;b public.sector_breakdowns;ii public.maintenance_inventory_items;p public.vehicle_maintenance_parts;n bigint;begin
 insert into auth.users(id,email) values(g,'cycle-garage@x.iq'),(m,'cycle-manager@x.iq'),(st,'cycle-station@x.iq'),(mt,'cycle-maintenance@x.iq'),(op,'cycle-ops@x.iq');insert into public.user_roles(user_id,role) values(g,'central_garage_officer'),(m,'department_manager'),(st,'transfer_station'),(mt,'maintenance'),(op,'ops_room');insert into public.manager_profiles(user_id,shift,sectors) values(m,'morning',array[1]::smallint[]);
 perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',g::text,false);v:=public.garage_add_vehicle('آلية دورة','DB-CYCLE','P-CYCLE','C-CYCLE',g::text||'/x.webp','morning','سائق أول',1::smallint);perform public.garage_set_vehicle_shift_assignment(v.id,'evening','سائق ثان',2::smallint,'إضافة المسائي');perform public.garage_set_vehicle_shift_assignment(v.id,'night','سائق ثالث',3::smallint,'إضافة الليلي');select count(*) into n from public.garage_vehicle_shift_assignments_list(v.id) where ends_at is null;if n<>3 then raise exception 'THREE_SHIFT_ASSIGNMENTS_FAIL';end if;d:=public.garage_record_shift_departure(v.id,'morning',null,m);select count(*) into n from public.vehicle_portal_link_health(now()-interval '1 day')where departure_id=d.id and link_status='ok' and notification_count=1;if n<>1 then raise exception 'GARAGE_MANAGER_LINK_HEALTH_FAIL';end if;
 perform set_config('request.jwt.claim.sub',m::text,false);select count(*) into n from public.manager_vehicle_trips_for_day((now()at time zone 'Asia/Baghdad')::date)where id=d.id;if n<>1 then raise exception 'MANAGER_INBOX_DELIVERY_FAIL';end if;d:=public.sector_confirm_vehicle_arrival(d.id,null);b:=public.sector_submit_breakdown(v.db_number,'عطل قصير','إصلاح في الموقع');if b.departure_id<>d.id or b.vehicle_id<>v.id then raise exception 'LEGACY_BREAKDOWN_NOT_LINKED_TO_ACTIVE_TRIP';end if;b:=public.sector_return_vehicle_to_work(b.id,'أصلح في الموقع وعادت للعمل');l:=public.sector_send_vehicle_to_station(d.id,'الزيارة الأولى');begin perform public.sector_submit_breakdown(v.db_number,'عطل أثناء الطريق',null);raise exception 'BREAKDOWN_OUTSIDE_SITE_ACCEPTED';exception when others then if sqlerrm='BREAKDOWN_OUTSIDE_SITE_ACCEPTED' then raise;end if;if sqlerrm not like '%BREAKDOWN_ACTIVE_TRIP_NOT_AT_SITE%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',st::text,false);l:=public.station_confirm_vehicle_arrival(l.id,null);l:=public.station_dispatch_vehicle(d.id,'work_site','عودة أولى');
 perform set_config('request.jwt.claim.sub',m::text,false);l:=public.sector_confirm_vehicle_site_return(l.id,null);l:=public.sector_send_vehicle_to_station(d.id,'الزيارة الثانية');
 perform set_config('request.jwt.claim.sub',st::text,false);l:=public.station_confirm_vehicle_arrival(l.id,null);l:=public.station_dispatch_vehicle(d.id,'garage','إنهاء للمحطة');
 perform set_config('request.jwt.claim.sub',g::text,false);d:=public.garage_record_return(d.id);select count(*) into n from public.vehicle_trip_legs where departure_id=d.id;if n<>4 then raise exception 'REPEATED_STATION_VISITS_FAIL %',n;end if;
 perform set_config('request.jwt.claim.sub',st::text,false);select visit_count into n from public.station_movement_days(10,0) where visit_day=(now() at time zone 'Asia/Baghdad')::date;if coalesce(n,0)<2 then raise exception 'STATION_DAY_VISIT_COUNT_FAIL %',n;end if;select count(*) into n from public.station_visits_for_day((now() at time zone 'Asia/Baghdad')::date,null,'dispatched',null) where departure_id=d.id;if n<>2 then raise exception 'STATION_VISIT_HISTORY_FAIL %',n;end if;
 perform set_config('request.jwt.claim.sub',g::text,false);d:=public.garage_record_shift_departure(v.id,'morning',null,m);perform set_config('request.jwt.claim.sub',m::text,false);d:=public.sector_confirm_vehicle_arrival(d.id,null);c:=public.sector_send_vehicle_to_maintenance(d.id,'عطل محرك','critical','لا تعمل');select * into b from public.sector_breakdowns where id=c.breakdown_id;if b.departure_id<>d.id or b.vehicle_id<>v.id then raise exception 'MAINTENANCE_BREAKDOWN_NOT_LINKED';end if;
 execute 'reset role';update public.vehicle_maintenance_cases set reported_at=now()-interval '2 days' where id=c.id;perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',mt::text,false);c:=public.maintenance_confirm_arrival(c.id,null);c:=public.maintenance_update_case(c.id,'waiting_parts',30,'تشخيص','بانتظار العمل','قطعة محرك',now()+interval '1 day','الفني الأول',500000,0,'بانتظار القطعة',mt);ii:=public.maintenance_inventory_create('P-CYCLE','مضخة محرك','قطعة',1);perform public.maintenance_inventory_receive(ii.id,2,250000,'استلام أولي');p:=public.maintenance_issue_inventory(c.id,ii.id,1,'للحالة');if p.part_status<>'issued' then raise exception 'MAINTENANCE_PART_ISSUE_FAIL';end if;begin perform public.maintenance_issue_inventory(c.id,ii.id,2,null);raise exception 'INSUFFICIENT_STOCK_ACCEPTED';exception when others then if sqlerrm='INSUFFICIENT_STOCK_ACCEPTED'then raise;end if;if sqlerrm not like '%MAINTENANCE_INVENTORY_INSUFFICIENT%'then raise;end if;end;p:=public.maintenance_install_issued_part(p.id);if p.part_status<>'installed'then raise exception 'MAINTENANCE_PART_INSTALL_FAIL';end if;select jsonb_array_length(public.maintenance_case_timeline(c.id)->'updates') into n;if n<1 then raise exception 'MAINTENANCE_TIMELINE_FAIL';end if;select count(*) into n from public.maintenance_case_days(10) where open_count>0;if n<1 then raise exception 'MAINTENANCE_DAILY_FOLDER_FAIL';end if;if c.completed_at is not null then raise exception 'MULTIDAY_MAINTENANCE_CLOSED';end if;c:=public.maintenance_update_case(c.id,'ready',100,'تم الإصلاح','اكتمل','ركبت القطعة',null);perform public.maintenance_register_attachment(c.id,c.id::text||'/proof.jpg','proof.jpg','image/jpeg',100,repeat('a',64),'بعد الإصلاح');begin perform public.maintenance_dispatch_vehicle(c.id,'work_site',null);raise exception 'UNAPPROVED_MAINTENANCE_DISPATCH_ACCEPTED';exception when others then if sqlerrm='UNAPPROVED_MAINTENANCE_DISPATCH_ACCEPTED' then raise;end if;if sqlerrm not like '%MAINTENANCE_READINESS_APPROVAL_REQUIRED%' then raise;end if;end;c:=public.maintenance_approve_readiness(c.id,'فحص التشغيل النهائي');if c.readiness_approved_at is null or c.readiness_approved_by<>mt then raise exception 'MAINTENANCE_READINESS_APPROVAL_FAIL';end if;c:=public.maintenance_dispatch_vehicle(c.id,'work_site',null);
 perform set_config('request.jwt.claim.sub',m::text,false);select * into l from public.vehicle_trip_legs where departure_id=d.id and destination_type='work_site' and arrived_at is null;l:=public.sector_confirm_vehicle_site_return(l.id,'عادت للعمل');select count(*) into n from public.vehicle_maintenance_cases where id=c.id and status='returned_to_work' and completed_at is not null;if n<>1 then raise exception 'MAINTENANCE_RETURN_WORK_FAIL';end if;
 execute 'reset role';update public.garage_departures set departed_at=now()-interval '2 days',arrived_at=now()-interval '13 hours' where id=d.id;update public.vehicle_trip_legs set departed_at=now()-interval '13 hours',arrived_at=case when arrived_at is null then null else now()-interval '13 hours' end where departure_id=d.id;perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',op::text,false);select count(*) into n from public.operational_live_alerts(null,null,null) where alert_type='trip_stale' and departure_id=d.id;if n<>1 then raise exception 'OPS_LIVE_ALERT_FAIL';end if;select count(*) into n from public.operational_vehicle_movements(current_date-3,current_date+1);if n<5 then raise exception 'OPS_MOVEMENTS_FAIL';end if;select count(*) into n from public.operational_garage_trips(current_date-3,current_date+1);if n<2 then raise exception 'OPS_GARAGE_FAIL';end if;select count(*) into n from public.operational_maintenance_cases(current_date-3,current_date+1);if n<1 then raise exception 'OPS_MAINTENANCE_FAIL';end if;select count(*) into n from public.operational_station_visits(current_date-3,current_date+1);if n<2 then raise exception 'OPS_STATION_VISITS_FAIL';end if;select count(*) into n from public.operational_vehicle_kpis(current_date-3,current_date+1,null,null,null) where station_visit_count=2 and productive_minutes>=0 and movement_minutes>=0 and station_minutes>=0;if n<1 then raise exception 'OPS_COMPOSITE_KPI_FAIL';end if;
 raise notice '✅ دورات المحطة المتكررة/الصيانة متعددة الأيام/العودة للعمل/3 شفتات/غرفة العمليات ناجحة';end$$;
